with valid_customers as (select * from customers where age between 62 and 65 and (lower(trim(email)) = 'henry@startup.io' or segment in ('Consumer', 'SMB'))), summary as (select year(signup_date) as signup_year, sum(case when country = 'TH' then 1 else 0 end) as th_count from valid_customers group by year(signup_date)) select signup_year, th_count from summary where th_count >= 40 order by 1 desc, th_count desc limit 50;
